class Solution:
    def minSwaps(self, nums: List[int]) -> int:
        n = len(nums)
        evens = sum(1 for x in nums if x % 2 == 0)
        if abs(n - 2 * evens) > 1:
            return -1
        def cost(start):
            mis, p = 0, start
            for x in nums:
                if x % 2 != p:
                    mis += 1
                p ^= 1
            return mis // 2
        res = []
        if evens == (n + 1) // 2:
            res.append(cost(0))
        if n - evens == (n + 1) // 2:
            res.append(cost(1))
        return min(res)

