class Solution {
public:
    int minSwaps(vector<int>& nums) {
        int n = nums.size(), evens = 0;
        for (int x : nums) evens += (x % 2 == 0);
        if (abs(n - 2 * evens) > 1) return -1;
        auto cost = [&](int start) {
            int mis = 0, p = start;
            for (int x : nums) {
                if (x % 2 != p) mis++;
                p ^= 1;
            }
            return mis / 2;
        };
        int ans = INT_MAX;
        if (evens == (n + 1) / 2) ans = min(ans, cost(0));
        if (n - evens == (n + 1) / 2) ans = min(ans, cost(1));
        return ans;
    }
};

