class Solution {
    public int minSwaps(int[] nums) {
        int n = nums.length, evens = 0;
        for (int x : nums) if (x % 2 == 0) evens++;
        if (Math.abs(n - 2 * evens) > 1) return -1;
        int ans = Integer.MAX_VALUE;
        if (evens == (n + 1) / 2) ans = Math.min(ans, cost(nums, 0));
        if (n - evens == (n + 1) / 2) ans = Math.min(ans, cost(nums, 1));
        return ans;
    }
    private int cost(int[] nums, int start) {
        int mis = 0, p = start;
        for (int x : nums) {
            if (x % 2 != p) mis++;
            p ^= 1;
        }
        return mis / 2;
    }
}

