var minSwaps = function(nums) {
    const n = nums.length;
    const evens = nums.filter(x => x % 2 === 0).length;
    if (Math.abs(n - 2 * evens) > 1) return -1;
    const cost = (start) => {
        let mis = 0, p = start;
        for (const x of nums) {
            if (Math.abs(x % 2) !== p) mis++;
            p ^= 1;
        }
        return Math.floor(mis / 2);
    };
    let ans = Infinity;
    if (evens === Math.ceil(n / 2)) ans = Math.min(ans, cost(0));
    if (n - evens === Math.ceil(n / 2)) ans = Math.min(ans, cost(1));
    return ans;
};
